    public static VoxelShape crystal(Direction facing) { return CRYSTAL[index(facing)]; }
    public static VoxelShape analysis(Direction facing) { return ANALYSIS[index(facing)]; }
    private static int index(Direction facing) {
        return switch (facing) { case EAST -> 1; case SOUTH -> 2; case WEST -> 3; default -> 0; };
    }
    private static VoxelShape[] create(int[][] boxes) {
        VoxelShape shape = Shapes.empty();
        for (int[] b : boxes) shape = Shapes.or(shape, Block.box(b[0],b[1],b[2],b[3],b[4],b[5]));
        VoxelShape[] result = new VoxelShape[4];
        result[0] = shape.optimize();
        for (int i=1; i<4; i++) {
            VoxelShape[] rotated = {Shapes.empty()};
            result[i-1].forAllBoxes((x0,y0,z0,x1,y1,z1) -> rotated[0] = Shapes.or(rotated[0], Shapes.box(1-z1,y0,x0,1-z0,y1,x1)));
            result[i] = rotated[0].optimize();
        }
        return result;
    }
